// 1. Pegar o texto completo da mensagem
const mensagem = $input.first().json.input || $input.first().json.text || $input.first().json.message?.text || '';

// 2. Função auxiliar para extrair um campo específico
function extrairCampo(texto, marcador) {
  const regex = new RegExp(`${marcador}:\\s*(.+?)(?:\\n|$)`, 'i');
  const resultado = texto.match(regex);
  return resultado ? resultado[1].trim() : '';
}

// --- DADOS DE DESENHO ---
const numeroProjeto = extrairCampo(mensagem, 'Numero_projeto');
const cliente = extrairCampo(mensagem, 'Cliente');
const ideia = extrairCampo(mensagem, 'Ideia');
const dataAdicao = extrairCampo(mensagem, 'Adição');
const dataInicio = extrairCampo(mensagem, 'Inicio');
const dataFim = extrairCampo(mensagem, 'Fim');
const tempo = extrairCampo(mensagem, 'Tempo');
const entrega = extrairCampo(mensagem, 'Entrega');
const ganho = extrairCampo(mensagem, 'Ganho');
const status = extrairCampo(mensagem, 'Status');

// --- DADOS DE JOGO ---
const idJogo = extrairCampo(mensagem, 'id');
const zerado = extrairCampo(mensagem, 'zerado');
const dataZerada = extrairCampo(mensagem, 'data_zerada');
const nota = extrairCampo(mensagem, 'nota');
const review = extrairCampo(mensagem, 'review');

// 3. Lógica de decisão: É desenho ou jogo?
// Se tiver "Numero_projeto" ou "Cliente", é desenho.
if (numeroProjeto || cliente) {
  return {
    json: {
      tipo_requisicao: 'desenho', // 👈 Ajuda a rotear no n8n
      Numero_Projeto: numeroProjeto,
      Cliente: cliente,
      Ideia: ideia,
      Data_Adicao: dataAdicao,
      Data_Inicio: dataInicio,
      Data_Fim: dataFim,
      Tempo: tempo,
      Entrega: entrega,
      Ganho: ganho,
      status: status
    }
  };
} 
// Se tiver "idJogo" e algum campo de review, é jogo.
else if (idJogo && (zerado || dataZerada || nota || review)) {
  const jsonJogo = { 
    tipo_requisicao: 'jogo', // 👈 Ajuda a rotear no n8n
    id: parseInt(idJogo)
  };

  // Só adiciona os campos se você tiver digitado algo
  if (zerado) jsonJogo.zerado = /sim|true|1/i.test(zerado);
  if (dataZerada) jsonJogo.data_zerada = dataZerada;
  if (nota) jsonJogo.nota = parseInt(nota);
  if (review) jsonJogo.review = review;

  return { json: jsonJogo };
} 
// Se não for nenhum dos dois
else {
  return {
    json: {
      tipo_requisicao: 'desconhecido',
      erro: 'Não foi possível identificar se é desenho ou jogo.',
      mensagem_original: mensagem
    }
  };
}

