return $input.all().map(item => {
  const json = item.json;

  // Função que converte qualquer coisa em boolean seguro
  function paraBool(valor) {
    // Se já é boolean de verdade, retorna
    if (typeof valor === 'boolean') return valor;

    // Se é null, undefined ou string vazia, retorna false
    if (valor === null || valor === undefined || valor === '') return false;

    // Se é array (n8n às vezes manda checkbox assim), pega o primeiro
    if (Array.isArray(valor)) valor = valor[0];

    // Se é string, converte
    if (typeof valor === 'string') {
      const normalizado = valor.toLowerCase().trim();
      return normalizado === 'true' 
          || normalizado === 't' 
          || normalizado === '1' 
          || normalizado === 'yes'
          || normalizado === 'sim';
    }

    // Se é número
    if (typeof valor === 'number') return valor !== 0;

    // Fallback
    return false;
  }

  // Cria uma cópia do json com os campos convertidos
  return {
    json: {
      ...json,
      // Adapta os nomes dos campos pros que vão pro Postgres
      // Troca "zerado" e "eu_queria" pelos nomes reais do seu form
      zerado: paraBool(json.zerado),
      eu_queria: paraBool(json.eu_queria),
      multiplas_versoes: paraBool(json.multiplas_versoes),

      // Mantém os outros campos intactos
      nome: json.nome,
      plataforma: json.plataforma,
      preco_pago: json.preco_pago,
      preco_cheio: json.preco_cheio,
      lancamento: json.lancamento,
      data_compra: json.data_compra,
    }
  };
});

const items = $input.all();

if (items.length === 0) {
  return [{ json: { mensagem: '☀️ Bom dia! Nada nos próximos 2 dias. Dia livre.' } }];
}

const grupos = { atrasado: [], hoje: [], amanha: [], depois: [] };
items.forEach(i => grupos[i.json.grupo]?.push(i.json));

const emojiPrio = { alta: '🔴', media: '🟡', baixa: '🟢' };

function formatar(lista) {
  return lista.map(a => {
    const h = a.hora ? ` ${a.hora.slice(0,5)}` : '';
    const e = emojiPrio[a.prioridade] || '⚪';
    let linha = `${e} <b>${a.titulo}</b>${h}`;
    if (a.descricao) linha += `\n   <i>${a.descricao}</i>`;
    return linha;
  }).join('\n');
}

const linhas = ['☀️ <b>Bom dia! Sua agenda:</b>', ''];

if (grupos.atrasado.length) {
  linhas.push(`🚨 <b>ATRASADO (${grupos.atrasado.length})</b>`);
  linhas.push(formatar(grupos.atrasado));
  linhas.push('');
}
if (grupos.hoje.length) {
  linhas.push(`📌 <b>HOJE (${grupos.hoje.length})</b>`);
  linhas.push(formatar(grupos.hoje));
  linhas.push('');
}
if (grupos.amanha.length) {
  linhas.push(`📅 <b>AMANHÃ (${grupos.amanha.length})</b>`);
  linhas.push(formatar(grupos.amanha));
  linhas.push('');
}
if (grupos.depois.length) {
  linhas.push(`🔔 <b>EM 2 DIAS (${grupos.depois.length})</b>`);
  linhas.push(formatar(grupos.depois));
}

return [{ json: { mensagem: linhas.join('\n').trim() } }];

const items = $input.all();
